if (element.getAttribute('aria-label') === 'Sign in') {
  element.style.display = 'none'
} else if (element.tagName === 'A' && element.getAttribute('aria-label') === 'Sign in') {
  const renderer = element.closest('ytd-button-renderer')
  if (renderer) renderer.style.display = 'none'
}
